<script setup lang="ts">
import type { PublicOfferingData } from '../../../../../packages/contracts/v2/public_catalog/generated'
import { claimLabels, missingLabels, scopeKeys, scopeLabels, scopeText } from './presentation'
defineProps<{ offering: PublicOfferingData; selected?: boolean; compared?: boolean; compareDisabled?: boolean; compact?: boolean }>()
const emit = defineEmits<{ select: []; compare: []; evidence: [id: string] }>()
</script>
<template>
  <article class="offering-card" :class="{selected,compact}" :data-testid="`catalog-offering-${offering.id}-${offering.version}`">
    <div class="card-top"><span>{{ offering.entry_year }} · {{ offering.scope.country }} · 本科</span><span class="published">已发布快照</span></div>
    <h3>{{ offering.institution_name }}</h3><p class="program">{{ offering.program_name }}</p>
    <p v-if="offering.is_synthetic" class="demo"><strong>DEMO · 合成项目</strong>，不是真实学校招生依据。</p>
    <dl class="reference"><div><dt>发布 / 项目版本</dt><dd>{{ offering.release_id }} / v{{ offering.version }}</dd></div><div><dt>要求快照 SHA256</dt><dd>{{ offering.requirements_version }}</dd></div></dl>
    <details><summary>查看完整适用范围</summary><dl class="scope"><div v-for="key in scopeKeys" :key="key"><dt>{{ scopeLabels[key] }}</dt><dd>{{ scopeText(offering.scope[key]) }}</dd></div></dl></details>
    <div class="facts"><section v-for="(fact,index) in offering.facts" :key="index" class="fact"><div class="fact-title"><strong>{{ fact.field_key }}</strong><span>{{ claimLabels[fact.claim_kind] }}</span></div><p>{{ fact.value_text ?? `缺失：${fact.missing_reason ? missingLabels[fact.missing_reason] : '未知'}` }}<span v-if="fact.unit"> · {{ fact.unit }}</span></p><p v-if="fact.value_text !== null && fact.normalized_value !== fact.value_text" class="detail">类型化值 {{ fact.normalized_value ?? '未知' }} · 原声明保持</p><p class="detail">期间：{{ fact.period }} · 单位口径：{{ fact.unit_code }}</p><p v-if="fact.claim_kind === 'historical_statistic' || fact.fact_type === 'statistic'" class="detail">统计口径 {{ fact.statistics_basis }} · 人群 {{ fact.statistic_population ?? '未知' }} · 分母 {{ fact.statistic_denominator ?? '未知' }} · 届别 {{ fact.cohort_year ?? '未知' }} · 调查期 {{ fact.survey_period ?? '未知' }}</p><p class="detail">脚注：{{ fact.footnote_state === 'present' ? fact.footnote_text : fact.footnote_state === 'none' ? '明确无脚注' : '未知' }}</p><div v-if="fact.date_resolution" class="date-detail"><p>日期原文：{{ fact.date_resolution.original_text }}</p><p>精度 {{ fact.date_resolution.precision }} · 当地日期 {{ fact.date_resolution.local_date ?? '未知' }} · 时间 {{ fact.date_resolution.local_time ?? '未知' }} · 时区 {{ fact.date_resolution.timezone ?? '未知' }}</p><p>转换状态 {{ fact.date_resolution.conversion_status }} · 原文对照 {{ fact.date_resolution.source_alignment }} · 官方 UTC 未核定</p><p v-if="fact.date_resolution.calculated_utc_instant">计算候选 UTC：{{ fact.date_resolution.calculated_utc_instant }}（不是官方时刻）</p></div><button v-if="fact.evidence_id" type="button" class="evidence-button" :data-testid="`catalog-evidence-${fact.evidence_id}`" @click="emit('evidence',fact.evidence_id)">查看此发布的证据</button><p v-else class="detail">此事实没有公开证据引用。</p></section></div>
    <div class="dimensions"><span>历史竞争：未知</span><span>偏好匹配：未知</span><span>数据质量：未知</span></div>
    <div v-if="!compact" class="card-actions"><button type="button" :aria-pressed="!!selected" :data-testid="`catalog-select-${offering.id}-${offering.version}`" @click="emit('select')">{{ selected ? '已选为检查目标' : '选择此项目' }}</button><label><input type="checkbox" :checked="!!compared" :disabled="compareDisabled && !compared" :data-testid="`catalog-compare-${offering.id}-${offering.version}`" @change="emit('compare')">{{ compared ? '已加入比较' : '加入比较' }}</label></div>
  </article>
</template>
